#!/usr/bin/env python3
"""Build the human-readable report exclusively from saved derived metrics."""
import argparse,csv,json,pathlib
BASE=pathlib.Path(__file__).resolve().parents[1]
def main():
 p=argparse.ArgumentParser();p.add_argument('runs',nargs='+',type=pathlib.Path);a=p.parse_args()
 rows=list(csv.DictReader((a.runs[0]/'behavioral_results.csv').open()));summary=json.loads((a.runs[0]/'summary.json').read_text());comparison=list(csv.DictReader((BASE/'comparison/comparison.csv').open()));repro=json.loads((BASE/'comparison/reproducibility.json').read_text());validation=json.loads((BASE/'validation.json').read_text())
 lines=['# Переносимость на UC02 и UC03: результаты из сохранённых CSV','',f"Исходных контрактов: {repro['source_contracts']}; вариантов исходников: {repro['variant_sources']}; отдельных полных запусков: {repro['clean_process_launches']}; повторов на контракт: {repro['repetitions_per_source']}; основных испытаний: {repro['primary_trials']}; отдельных нормальных проб: {repro['legitimate_probes']}.",'','Повторы проверяют воспроизводимость, а не увеличивают число независимых контрактов. UC01 не перезапускался и не объединялся с этими результатами.','', '| Контракт | Сравнение | Классификация | Обычная функциональность сохранена |','|---|---|---|---|']
 labels={'additional observed protection':'дополнительная наблюдаемая защита','equal observed protection':'равная наблюдаемая защита','functional regression':'функциональная регрессия','security regression':'регрессия защиты','trade-off':'компромисс','inconclusive evidence':'неопределённый результат'}
 for r in comparison:lines.append(f"| {r['contract_id']} | {r['comparison']} | {labels[r['classification']]} | {r['all_legitimate_functionality_preserved']} |")
 lines+=['','Польза A+B относительно ОБОИХ индивидуальных компонентов не заявляется, если хотя бы одно сравнение — равенство.','', '| Контракт | Вариант | Сценарий | Внешний статус | Передано | D, единицы токена | D/a | Расход allowance | Нарушения |','|---|---|---|---|---:|---:|---|---:|---|']
 for r in rows:lines.append('| '+' | '.join([r['contract_id'],r['variant'],r['scenario'],'успех' if r['outer_transaction_status']=='1' else 'revert',r['delivered_delta'],r['acknowledged_shortfall_token_units'],r['normalized_shortfall'],r['allowance_consumed'],r['violated_invariant_ids']])+' |')
 lines+=['','Таблица показывает один полный запуск; совпадение всех сравниваемых поведенческих полей в чистом повторе: '+json.dumps(repro['behavioral_metrics_identical'])+'.','', '| Контракт | Вариант | Правильно обработанные отрицательные сценарии за повтор | Нормальные пробы | S1 | Нарушения применимых инвариантов за повтор |','|---|---|---|---|---|---:|']
 for cid,variants in summary.items():
  for v,s in variants.items():lines.append(f"| {cid} | {v} | {s['negative_scenarios_satisfied']}/{s['negative_scenarios_completed']} (ожидалось {s['negative_scenarios_expected']}; исключено {s['negative_scenarios_excluded_infrastructure']}) | {s['legitimate_probes_passed']}/{s['legitimate_probes_expected']} | {s['S1_legitimate_passed']} | {s['primary_invariant_violations']} |")
 lines+=['','I1 — успешное подтверждение без требуемой доставки/учёта; I4 — несоблюдение атомарного отказа. I2 и показатель утраченной записи Holders здесь неприменимы; они не приравнены к нулю. Величины D не являются доказанным финансовым ущербом. Показатели не складываются в шкалу и не пересчитываются в PES.','',f"Проверка доказательств: {validation['status']}; прежних файлов проверено без изменения: {validation['prior_files_preserved']}; файлов замороженного UC01 дополнительно проверено: {validation['UC01_frozen_files_verified']}; основных трасс сверено: {validation['primary_traces_crosschecked']}.",'','Ограничения: один получатель на batch, честные синтетические токены, только S1–S3, ограниченные величины без арифметического переполнения, отсутствие проверки прочих дефектов и функций. Разные compiler pins, размер операции и применимость учёта требуют раздельного представления контрактов, а не объединения с UC01 как идентичных повторностей.']
 (BASE/'generated_results.md').write_text('\n'.join(lines)+'\n')
if __name__=='__main__':main()
